#!/usr/bin/env bash
set -e
export LC_ALL=C

if [ "$#" -ne 1 ]; then
    echo "Usage: $0 <deps-file>" >&2
    exit 2
fi

input_file="$1"

awk '
BEGIN {
    # We will track:
    # all_pkgs[pkg] = 1
    # deps[pkg, dep] = 1
    # dep_count[pkg] = number of distinct deps
    # rev_deps[dep, pkg] = 1
}

# Remove comments
{
    sub(/#.*/, "")
    # Check if line is empty or only whitespace
    if ($0 ~ /^[ \t]*$/) next

    # Split by colon
    colon_idx = index($0, ":")
    if (colon_idx == 0) next

    pkg_str = substr($0, 1, colon_idx - 1)
    deps_str = substr($0, colon_idx + 1)

    # Trim pkg_str
    gsub(/^[ \t]+|[ \t]+$/, "", pkg_str)
    if (pkg_str == "") next

    all_pkgs[pkg_str] = 1

    # Parse deps
    n = split(deps_str, d_arr, /[ \t]+/)
    for (i = 1; i <= n; i++) {
        dep = d_arr[i]
        if (dep != "") {
            all_pkgs[dep] = 1
            if (!((pkg_str, dep) in deps)) {
                deps[pkg_str, dep] = 1
                dep_count[pkg_str]++
                rev_deps[dep, pkg_str] = 1
                rev_count[dep]++
                rev_list[dep, rev_count[dep]] = pkg_str
            }
        }
    }
}

END {
    # Initialize dep_count for any packages that had no deps
    for (p in all_pkgs) {
        if (! (p in dep_count)) {
            dep_count[p] = 0
        }
    }

    # Kahn algorithm with deterministic smallest package selection
    # We can keep an array of ready packages or just find the min ready package in each step.
    # Total packages is small (even big is < 100 packages), but let us check size.
    # Finding min among ready packages:
    # ready[p] = 1 if dep_count[p] == 0 and not emitted.
    for (p in all_pkgs) {
        if (dep_count[p] == 0) {
            ready[p] = 1
        }
    }

    emitted_count = 0
    total_pkgs = 0
    for (p in all_pkgs) total_pkgs++

    while (1) {
        # Find smallest ready package (byte order)
        found = 0
        min_p = ""
        for (p in ready) {
            if (!found || p < min_p) {
                min_p = p
                found = 1
            }
        }
        if (!found) break

        # Emit min_p
        print min_p
        delete ready[min_p]
        emitted[min_p] = 1
        emitted_count++

        # Decrement dep_count for rev_deps
        rc = rev_count[min_p]
        for (i = 1; i <= rc; i++) {
            dependent = rev_list[min_p, i]
            dep_count[dependent]--
            if (dep_count[dependent] == 0) {
                ready[dependent] = 1
            }
        }
    }

    if (emitted_count < total_pkgs) {
        # Collect remaining packages
        rem_count = 0
        for (p in all_pkgs) {
            if (! (p in emitted)) {
                rem_count++
                rem_pkgs[rem_count] = p
            }
        }
        # Sort remaining packages
        # Simple selection sort or insertion sort
        for (i = 1; i <= rem_count; i++) {
            min_idx = i
            for (j = i + 1; j <= rem_count; j++) {
                if (rem_pkgs[j] < rem_pkgs[min_idx]) {
                    min_idx = j
                }
            }
            if (min_idx != i) {
                tmp = rem_pkgs[i]
                rem_pkgs[i] = rem_pkgs[min_idx]
                rem_pkgs[min_idx] = tmp
            }
        }

        # Print to stderr: "cycle: " followed by remaining sorted separated by spaces
        err_msg = "cycle:"
        for (i = 1; i <= rem_count; i++) {
            err_msg = err_msg " " rem_pkgs[i]
        }
        print err_msg > "/dev/stderr"
        exit 1
    }
}
' "$input_file"
